-- AI LAB HUB — партія 2026-10-01: «Мультимедіа» → нові підкатегорії «AI-аватари» та «Видалення фону» — 6 нових продуктів, 6 прив'язок наявних
--   D-ID — AI-аватари
--   Hedra — AI-аватари
--   Captions — AI-аватари
--   Aragon AI — AI-аватари
--   remove.bg — Видалення фону
--   Pixelcut — Видалення фону
--   (наявний) HeyGen → AI-аватари
--   (наявний) Synthesia → AI-аватари
--   (наявний) Lensa → AI-аватари
--   (наявний) Photoroom → Видалення фону
--   (наявний) Clipdrop → Видалення фону
--   (наявний) Canva → Видалення фону
--
-- Застосування (phpMyAdmin хостингу, БД gu621051_ailabhublive): «Импорт» → *.sql.zip → «Импорт» (або SQL → вставити → Вперёд).
-- Без фіксованих id і без DROP / DELETE. @new обчислюється ДО вставки продукту (без ROW_COUNT()); продукт додається
-- лише якщо немає продукту з тим самим нормалізованим URL АБО назвою, інакше наявному лише додаються категорія й
-- підкатегорія. Id тарифів — за product_id + plan_name. Повторний запуск безпечний.
-- Автор — whitevelvetelf@gmail.com (id за email). Статус published, партнерство «Знайдено».
-- =====================================================================

INSERT IGNORE INTO `subcategories` (`category_id`, `name`, `name_en`, `slug`) SELECT c.`id`, 'AI-аватари', 'AI Avatars', 'ai-avatars' FROM `categories` c WHERE c.`slug` = 'multimedia' LIMIT 1;
INSERT IGNORE INTO `subcategories` (`category_id`, `name`, `name_en`, `slug`) SELECT c.`id`, 'Видалення фону', 'Background Removal', 'background-removal' FROM `categories` c WHERE c.`slug` = 'multimedia' LIMIT 1;

SET @uid = (SELECT `id` FROM `users` WHERE `email` = 'whitevelvetelf@gmail.com' LIMIT 1);

-- D-ID — AI-аватари
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'd-id.com' OR LOWER(`name`) = LOWER('D-ID'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'D-ID', NULL, 'https://www.d-id.com', NULL, NULL, 'Платформа відео з фотореалістичними AI-аватарами, що говорять: ролики для маркетингу, продажів і навчання, переклад відео та API для розробників.', 'A video platform with photorealistic talking AI avatars: clips for marketing, sales and training, video translation and an API for developers.', 'D-ID створює відео, у яких фотореалістичний AI-аватар промовляє ваш текст. У D-ID Studio можна обрати готового аватара чи зробити власного, додати сценарій і озвучення та отримати ролик для маркетингу, продажів, підтримки клієнтів або корпоративного навчання. Є переклад відео іншими мовами, інтерактивні відеоагенти та API для інтеграції в продукти. Хвилини відео оновлюються щомісяця й не переносяться. Тарифи при річній оплаті: Trial — безкоштовно 3 хвилини з водяним знаком; Lite — $4,70 на місяць ($56 на рік, 10 хв); Pro — $16 на місяць ($191 на рік, 15 хв); Advanced — $108 на місяць ($1 293 на рік, 100 хв); Enterprise — за запитом.', 'D-ID creates videos in which a photorealistic AI avatar speaks your script. In D-ID Studio you can pick a ready-made avatar or make your own, add a script and voice, and get a clip for marketing, sales, customer support or corporate training. It also offers video translation, interactive video agents and an API for integrating into products. Video minutes renew monthly and do not roll over. Plans billed annually: Trial — 3 free minutes with a watermark; Lite — $4.70 a month ($56 a year, 10 min); Pro — $16 a month ($191 a year, 15 min); Advanced — $108 a month ($1,293 a year, 100 min); Enterprise on request.', 'Фотореалістичні аватари, що говорять
Власні аватари й озвучення
Переклад відео
Інтерактивні відеоагенти та API', 'Photorealistic talking avatars
Custom avatars and voices
Video translation
Interactive video agents and API', 'Маркетологи, тренери й команди продажів, яким потрібні відео з ведучим без зйомок.', 'Marketers, trainers and sales teams that need presenter-led videos without filming.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'd-id.com' OR LOWER(`name`) = LOWER('D-ID')) ORDER BY `id` LIMIT 1);
