-- Hedra — AI-аватари
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hedra.com' OR LOWER(`name`) = LOWER('Hedra'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Hedra', NULL, 'https://www.hedra.com', NULL, NULL, 'Студія AI-відео з персонажами: оживлює фото чи згенерованого героя, синхронізує губи з голосом і дає доступ до провідних відеомоделей та API.', 'An AI character video studio: it brings a photo or generated character to life, syncs lips to a voice and gives access to leading video models and an API.', 'Hedra — платформа для створення відео з персонажами, що говорять. Завантажте фото або згенеруйте героя, додайте аудіо чи текст — і Hedra створить виразне відео з синхронізацією губ, мімікою та рухами. У студії також доступні провідні моделі генерації відео й зображень через єдиний інтерфейс, а розробники можуть використовувати API. Усі платні тарифи дозволяють комерційне використання. Тарифи: безкоштовний старт; Basic — $20 на місяць (2 000 кредитів); Pro — $50 (7 200 кредитів); Ultra — $100 (18 000 кредитів, командний доступ); Teams — $75 на місяць (14 400 кредитів); Enterprise — за запитом.', 'Hedra is a platform for creating videos with talking characters. Upload a photo or generate a character, add audio or text, and Hedra creates an expressive video with lip sync, facial expressions and movement. The studio also gives access to leading video and image generation models through one interface, and developers can use the API. All paid plans include commercial use rights. Plans: free to start; Basic — $20 a month (2,000 credits); Pro — $50 (7,200 credits); Ultra — $100 (18,000 credits, team access); Teams — $75 a month (14,400 credits); Enterprise on request.', 'Відео з персонажами, що говорять
Синхронізація губ, міміка й рухи
Провідні відеомоделі в одній студії
API та комерційне використання', 'Talking character videos
Lip sync, expressions and movement
Leading video models in one studio
API and commercial use', 'Контент-мейкери, аніматори, маркетологи й розробники, які роблять відео з персонажами.', 'Content creators, animators, marketers and developers making character videos.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
