-- Captions — AI-аватари
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'captions.ai' OR LOWER(`name`) = LOWER('Captions'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Captions', NULL, 'https://www.captions.ai', NULL, NULL, 'AI-застосунок для коротких відео: автоматичні субтитри, монтаж, AI-аватари, які говорять ваш текст, і переклад відео для соцмереж.', 'An AI app for short-form video: automatic captions, editing, AI avatars that speak your script and video translation for social media.', 'Captions допомагає швидко створювати відео для соцмереж. Застосунок автоматично додає стильні субтитри, прибирає паузи й монтує ролик, а AI-аватари можуть промовляти ваш сценарій, тож відео можна зробити без зйомки себе. Доступні переклад і дубляж відео іншими мовами та інші AI-інструменти для монтажу. Працює у вебі та мобільному застосунку. Оплата — кредитами: платні тарифи коштують від $24,99 на місяць (500 кредитів) до $69,99 на місяць (1 400 кредитів); для компаній — Enterprise з індивідуальними обсягами.', 'Captions helps you make social media videos quickly. The app adds stylish captions automatically, removes pauses and edits the clip, and AI avatars can speak your script so you can make a video without filming yourself. It also offers video translation and dubbing and other AI editing tools. It works on the web and in a mobile app. Usage is credit-based: paid plans range from $24.99 a month (500 credits) to $69.99 a month (1,400 credits); companies can get Enterprise with custom volumes.', 'Автоматичні субтитри й монтаж
AI-аватари, що говорять ваш текст
Переклад і дубляж відео
Веб і мобільний застосунок', 'Automatic captions and editing
AI avatars that speak your script
Video translation and dubbing
Web and mobile app', 'Блогери, SMM-фахівці та малий бізнес, які регулярно публікують короткі відео.', 'Creators, social media managers and small businesses that post short videos regularly.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
